import json, re

pairs = json.load(open("/app/re.json"))
fen = "rnb1k1nr/p2p1ppp/3B4/1p1NPN1P/6P1/3P1Q2/P1P5/q4Kb1 w kq - 0 1"

def show(tag, s, maxlen=200):
    print('---', tag, '(len %d)' % len(s))
    for ln in s.split('\n')[:4]:
        print('   |', ln[:maxlen])

show('start', fen)
i = 0
# find stage boundaries by scanning pattern shapes
stage = 'expand'
for p, r in pairs:
    if p == r'^[^\n]*\n?':
        stage = 'gen->R1'
    elif p == r'^(?=\S)':
        stage = 'R2'
    elif p.startswith(r'(?<=\n)') and 'KR0' in p:
        stage = 'R3'
    elif p.startswith(r'(?<=\n)[^\n]{0,70}') and stage not in ('R6',):
        stage = 'R4'
    elif p.startswith(r'(?<=\n)([^\\n]{71}) b '):
        stage = 'R5'
    elif p in (r'^\n', r'\n$'):
        stage = 'R6'
    fen = re.sub(p, r, fen)
    if stage in ('gen->R1', 'R2', 'R6') or (stage == 'R4' and p.endswith('K')):
        show(stage, fen)
        # only show once per stage
        break_marker = stage
show('final', fen)

