#!/usr/bin/env python3
"""Stress test: random positions from random walks + targeted edge cases."""
import chess
import json
import random
import re
import sys
import time

pairs = json.load(open('/app/re.json'))


def run_solution(fen):
    for pattern, repl in pairs:
        fen = re.sub(pattern, repl, fen)
    return [" ".join(x.split(" ")[:-2]) for x in fen.split("\n")]


def reference(fen):
    board = chess.Board(fen)
    ref = set()
    for move in board.legal_moves:
        if move.promotion and move.promotion != chess.QUEEN:
            continue
        bc = board.copy()
        bc.push(move)
        ref.add(" ".join(bc.fen().split(" ")[:-2]))
    return ref


def check(fen, tag):
    ours = run_solution(fen)
    ref = reference(fen)
    bad = []
    for x in ours:
        if x not in ref and x.rpartition(" ")[0] + " -" not in ref:
            bad.append(('EXTRA', x))
    if len(ours) != len(ref):
        bad.append(('COUNT', len(ours), len(ref), sorted(ref - set(ours))[:3]))
    # dedupe check: our lines should be distinct (ref is a set)
    if len(set(ours)) != len(ours):
        bad.append(('DUPES', len(ours) - len(set(ours))))
    if bad:
        print('FAIL [%s] %s' % (tag, fen))
        for b in bad[:6]:
            print('   ', b)
        return False
    print('ok   [%s] %d moves' % (tag, len(ref)))
    return True


def main():
    random.seed(int(sys.argv[1]) if len(sys.argv) > 1 else 42)
    ok = True

    # targeted edge cases
    edge = [
        ('EP-pin1', 'rnbqkbnr/ppp1pppp/8/1p2p3/8/PPPP1PPP/8/RNBQKBNR w KQkq b6 0 3'),
        ('EP-basic', 'rnbqkbnr/pp1ppppp/8/2p2P2/8/8/PPPP1PPP/RNBQKBNR w KQkq c5 0 3'),
        ('EP-mate-threat', 'r1bqkbnr/pp2pppp/2n1P3/3p4/8/8/PPPP1PPP/RNBQKBNR w KQkq d5 0 4'),
        ('promo1', '8/1P6/8/8/8/8/8/4K2k w - - 0 1'),
        ('promo2', 'k7/1P1P4/8/8/8/8/8/4K3 w - - 0 1'),
        ('castling-open', '4k3/8/8/8/8/8/8/4K2R w K - 0 1'),
        ('castling-blocked', '4k3/8/8/8/8/5q2/8/4K2R w K - 0 1'),
        ('check-escape', 'r1bqkbnr/pppp1ppp/2n5/4p3/2B1P3/5Q2/PPPP1PPP/RNB1K1NR w KQkq - 0 5'),
        ('skewer-ep', '2kr3r/1p6/8/1P1P4/8/8/8/4K2k w - f6 0 3'),
        ('two-eps', '3r2k1/pPp5/8/8/8/8/8/4K2k w - b6 0 4'),
    ]
    for tag, fen in edge:
        try:
            b = chess.Board(fen)
            if not b.is_valid():
                print('skip invalid [%s]' % tag)
                continue
            ok &= check(fen, tag)
        except Exception as e:
            print('ERR [%s]: %s' % (tag, e))
            ok = False

    # random walks from initial position
    for i in range(300):
        board = chess.Board()
        depth = random.randint(1, 40)
        try:
            for _ in range(depth):
                mv = random.choice(list(board.legal_moves))
                board.push(mv)
        except Exception:
            continue
        if board.turn != chess.WHITE:
            board.pop()
        if board.is_game_over():
            continue
        fen = board.fen()
        ok &= check(fen, 'rand%d' % i)
        if not ok and i > 10:
            break

    print('RESULT:', 'ALL OK' if ok else 'FAILURES')
    return 0 if ok else 1


if __name__ == '__main__':
    sys.exit(main())

