import json, re
pairs = json.load(open('/app/re.json'))
fen = 'rn1qkbn1/p2ppp1r/b1B5/1pp3pp/6P1/1PP1P3/P2P1P1P/RNBQK1NR w KQq - 1 10'
lines = fen.split('\n')
history = {l: [] for l in lines}  # line -> list of (pat_idx, prev_line)
for i, (p, r) in enumerate(pairs):
    newlines = re.sub(p, r, fen).split('\n')
    # map: find which old lines produced which new lines (re.sub preserves order roughly)
    # simpler: for each new line not in old lines -> created; for each changed line record
    oldset = set(lines)
    for nl in newlines:
        if nl not in oldset and nl:
            history.setdefault(nl, []).append((i, 'CREATED'))
        elif nl in oldset:
            pass
    # record changes: match by position
    if len(newlines) != len(lines):
        # realign: use difflib
        import difflib
        sm = difflib.SequenceMatcher(None, lines, newlines)
        for tag, i1, i2, j1, j2 in sm.get_opcodes():
            if tag == 'replace':
                for k in range(max(i2-i1, j2-j1)):
                    ol = lines[i1+k] if i1+k < i2 else None
                    nl = newlines[j1+k] if j1+k < j2 else None
                    if nl and nl != fen and nl in history:
                        pass
                    if nl:
                        history.setdefault(nl, []).append((i, 'CHANGED from %s' % (ol[:40] if ol else '?')))
            elif tag == 'insert':
                for k in range(j1, j2):
                    history.setdefault(newlines[k], []).append((i, 'CREATED'))
    lines = newlines
    fen = '\n'.join(lines)

# final extra lines of interest
for target in ['Bn1qkbn1', 'RNBQ1KNR', 'RNBQ2NR']:
    for l in lines:
        if target in l:
            print('FINAL:', l[:105])
            for idx, how in history.get(l, [])[:6]:
                print('    #%d %s' % (idx, how[:90]))
            print()
