import chess, json, re
pairs = json.load(open('/app/re.json'))
def run(fen):
    for p, r in pairs:
        fen = re.sub(p, r, fen)
    return [" ".join(x.split(" ")[:-2]) for x in fen.split("\n")]
def ref(fen):
    b = chess.Board(fen); s = set()
    for m in b.legal_moves:
        if m.promotion and m.promotion != chess.QUEEN: continue
        bc = b.copy(); bc.push(m); s.add(" ".join(bc.fen().split(" ")[:-2]))
    return s
for fen in ['rnb2bkr/pp1pp1pp/7Q/3Pq3/1pNP1p1N/8/PPP2PPP/R1B1K2R w K - 4 15',
            'rnbqkbnr/pppppppp/8/8/8/8/PPPPPPPP/RNBQKBNR w KQkq - 0 1']:
    ours = run(fen); R = ref(fen)
    bad = [x for x in ours if x not in R and x.rpartition(' ')[0]+' -' not in R]
    miss = R - set(ours)
    print('%s: ours=%d ref=%d bad=%d miss=%d' % (fen[:20], len(ours), len(R), len(bad), len(miss)))
    for x in bad[:4]: print('   EXTRA:', x[:100])
    for x in sorted(miss)[:4]: print('   MISS:', x[:100])
